async function a(s,n,r){try{const o=new AbortController,i=setTimeout(()=>o.abort(),15e3),t=await fetch("/api/send-push-notification",{method:"POST",headers:{"Content-Type":"application/json"},signal:o.signal,body:JSON.stringify({title:s,message:n,target:"admins",link:r})});clearTimeout(i);const e=await t.json();t.ok?console.log("[Push] Success! Notification ID:",e.id):console.error("[Push] API Error:",e.error)}catch(o){console.error("[Push] Critical Failure:",o)}}export{a as s};
